def total_match(lst1, lst2):
    total_chars1 = sum(len(word) for word in lst1)
    total_chars2 = sum(len(word) for word in lst2)

    if total_chars1 == total_chars2:
        return lst1
    elif total_chars1 < total_chars2:
        return lst1
